def _is_free(a: dict) -> bool:
    return a.get("free") or a.get("no_key") or (
        str(a.get("auth", "")).strip().lower() in ("", "no", "none", "n/a")
    )

BY_CATEGORY: Dict[str, List[Dict]] = {}
for _a in API_REGISTRY:
    BY_CATEGORY.setdefault(_a.get("category", "uncategorized"), []).append(_a)

BY_SOURCE: Dict[str, List[Dict]] = {}
for _a in API_REGISTRY:
    BY_SOURCE.setdefault(_a.get("source", "unknown"), []).append(_a)

# === 缺失导出（历史遗留：旧版有 FREE_ONLY/stats，新版没补）===
FREE_ONLY: List[Dict] = [_a for _a in API_REGISTRY if _is_free(_a)]


def stats() -> Dict:
    """Registry 总览 stats — dashboard /api/apis/stats 用。"""
    return {
        "total": len(API_REGISTRY),
        "no_key": len(NO_KEY_APIS),
        "free": len(FREE_ONLY),
        "categories": len(BY_CATEGORY),
        "sources": len(BY_SOURCE),
        "top_categories": [
            {"name": c, "count": len(v)}
            for c, v in sorted(BY_CATEGORY.items(), key=lambda x: -len(x[1]))[:10]
        ],
        "top_sources": [
            {"name": s, "count": len(v)}
            for s, v in sorted(BY_SOURCE.items(), key=lambda x: -len(x[1]))[:10]
        ],
    }

def search(q: str = "", no_key_only: bool = False, free_only: bool = False,
           cat: str = "", limit: int = 50) -> List[Dict]:
    results = list(API_REGISTRY)
    if q:
        ql = q.lower()
        results = [a for a in results if ql in (
            f"{a.get('name','')} {a.get('description','')} {a.get('category','')}".lower()
        )]
    if no_key_only:
        results = [a for a in results if _is_free(a)]
    if free_only:
        results = [a for a in results if a.get("free", _is_free(a))]
    if cat:
        results = [a for a in results if a.get("category") == cat]
    return results[:limit]
